<?php require "config/db.php"; if(isset($_POST["add"])){ $id=(int)$_POST["food_id"]; $s=$pdo->prepare("SELECT id FROM foods WHERE id=? AND is_available=1"); $s->execute([$id]); if($s->fetch()){ $_SESSION["cart"][$id]=($_SESSION["cart"][$id]??0)+1; } header("Location: cart.php"); exit; } if(isset($_POST["update"])){ foreach(($_POST["qty"]??[]) as $id=>$qty){ $id=(int)$id;$qty=(int)$qty;if($qty<=0)unset($_SESSION["cart"][$id]);else $_SESSION["cart"][$id]=min($qty,20); } header("Location: cart.php");exit;} if(isset($_GET["remove"])){unset($_SESSION["cart"][(int)$_GET["remove"]]);header("Location: cart.php");exit;} $items=[];$total=0; foreach($_SESSION["cart"]??[] as $id=>$qty){$s=$pdo->prepare("SELECT * FROM foods WHERE id=?");$s->execute([$id]);if($f=$s->fetch()){$f["qty"]=$qty;$f["line"]=$qty*(float)$f["price"];$total+=$f["line"];$items[]=$f;}} ?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Your cart | Foody Spot</title><link rel="stylesheet" href="assets/css/style.css"></head><body><?php include "includes/nav.php"; ?><main class="container page"><div class="page-head"><span class="eyebrow">ALMOST THERE</span><h1>Your cart<span>.</span></h1></div><?php if(!$items): ?><div class="empty-panel"><h2>Your cart is feeling lonely.</h2><p>Add something delicious from our menu.</p><a class="btn" href="menu.php">Browse menu →</a></div><?php else: ?><form method="post"><div class="cart-list"><?php foreach($items as $it): ?><div class="cart-row"><img src="<?= h($it["image_url"]) ?>" alt=""><div class="cart-desc"><h3><?= h($it["name"]) ?></h3><small>₹<?= number_format($it["price"],2) ?> each</small></div><input class="qty" type="number" min="0" max="20" name="qty[<?= (int)$it["id"] ?>]" value="<?= (int)$it["qty"] ?>"><strong>₹<?= number_format($it["line"],2) ?></strong><a class="remove" href="cart.php?remove=<?= (int)$it["id"] ?>">Remove</a></div><?php endforeach; ?></div><div class="cart-summary"><button class="btn btn-outline" name="update">Update cart</button><h2>Total: ₹<?= number_format($total,2) ?></h2><a class="btn" href="checkout.php">Proceed to checkout →</a></div></form><?php endif; ?></main><?php include "includes/footer.php"; ?></body></html>